          [value]="fromInput().terms"
          (input)="setFrom('terms', value($event)); termsTouched = true; settingsError.set('')"
        />
        @for (g of grades; track g) {
          <label [for]="'setting-terms-' + g">Terms for grade {{ g }} in days (blank: the sheet's terms)</label>
          <input
            [id]="'setting-terms-' + g"
